#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_N 1000
#define MAX_M 10000

typedef struct Edge {
    int to, cost;
    struct Edge *next;
} Edge;

Edge *graph[MAX_N];
int dist[MAX_N];
int visited[MAX_N];

void add_edge(int from, int to, int cost) {
    Edge *e = (Edge*)malloc(sizeof(Edge));
    e->to = to;
    e->cost = cost;
    e->next = graph[from];
    graph[from] = e;
}

void dijkstra(int start, int n) {
    for (int i = 0; i < n; i++) {
        dist[i] = INT_MAX;
        visited[i] = 0;
    }
    dist[start] = 0;

    for (int i = 0; i < n; i++) {
        int u = -1;
        int min_dist = INT_MAX;
        for (int j = 0; j < n; j++) {
            if (!visited[j] && dist[j] < min_dist) {
                min_dist = dist[j];
                u = j;
            }
        }
        if (u == -1) break;
        visited[u] = 1;

        for (Edge *e = graph[u]; e != NULL; e = e->next) {
            int v = e->to;
            int new_dist = dist[u] + e->cost;
            if (new_dist < dist[v]) {
                dist[v] = new_dist;
            }
        }
    }
}

int main() {
    int n, m, s, t1, t2;
    scanf("%d %d %d %d %d", &n, &m, &s, &t1, &t2);

    for (int i = 0; i < n; i++) {
        graph[i] = NULL;
    }

    for (int i = 0; i < m; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        add_edge(a, b, c);
    }

    // Find shortest path from source to t1
    dijkstra(s, n);
    int dist_s_t1 = dist[t1];
    int dist_s_t2 = dist[t2];

    // Find shortest path from t1 to t2
    dijkstra(t1, n);
    int dist_t1_t2 = dist[t2];

    // Find shortest path from t2 to t1
    dijkstra(t2, n);
    int dist_t2_t1 = dist[t1];

    // The two possible routes: s->t1->t2 or s->t2->t1
    int result1 = dist_s_t1 + dist_t1_t2;
    int result2 = dist_s_t2 + dist_t2_t1;

    // Check for overflow or unreachable paths
    if (dist_s_t1 == INT_MAX || dist_t1_t2 == INT_MAX) result1 = INT_MAX;
    if (dist_s_t2 == INT_MAX || dist_t2_t1 == INT_MAX) result2 = INT_MAX;

    int min_cost = (result1 < result2) ? result1 : result2;

    if (min_cost == INT_MAX) {
        printf("-1\n");
    } else {
        printf("%d\n", min_cost);
    }

    // Free memory
    for (int i = 0; i < n; i++) {
        Edge *e = graph[i];
        while (e != NULL) {
            Edge *temp = e;
            e = e->next;
            free(temp);
        }
    }

    return 0;
}

