void raddedge(int u, int v, int c) { redges[recnt]=(Edge){v,c,rhead[u]}; rhead[u]=recnt++; }

void dijkstra(int src, double *d, int rev) {
    for(int i=0;i<n;i++) d[i]=INF;
    d[src]=0;
    int vis[MAXN]={0};
    for(int iter=0;iter<n;iter++){
        int u=-1;
