#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef long long ll;

typedef struct Edge {
    int to;
    int next;
    ll w;
} Edge;

typedef struct HeapNode {
    int v;
    ll d;
} HeapNode;

typedef struct Heap {
    HeapNode *a;
    int sz, cap;
} Heap;

static void heap_init(Heap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 1));
    h->sz = 0;
    h->cap = cap;
}

static void heap_push(Heap *h, int v, ll d) {
    if (h->sz + 1 > h->cap) {
        h->cap *= 2;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->sz;
    while (i > 1 && h->a[i / 2].d > d) {
        h->a[i] = h->a[i / 2];
        i /= 2;
    }
    h->a[i].v = v;
    h->a[i].d = d;
}

static int heap_empty(Heap *h) {
    return h->sz == 0;
}

static HeapNode heap_pop(Heap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->sz--];
    int i = 1, child;
    while ((i << 1) <= h->sz) {
        child = i << 1;
        if (child + 1 <= h->sz && h->a[child + 1].d < h->a[child].d) child++;
        if (h->a[child].d >= last.d) break;
        h->a[i] = h->a[child];
        i = child;
    }
    h->a[i] = last;
    return ret;
}

static void add_edge(Edge *edges, int *head, int *idx, int u, int v, ll w) {
    edges[*idx].to = v;
    edges[*idx].w = w;
    edges[*idx].next = head[u];
    head[u] = (*idx)++;
}

static void dijkstra(int n, int start, int *head, Edge *edges, ll *dist) {
    const ll INF = (1LL << 60);
    for (int i = 1; i <= n; i++) dist[i] = INF;
    dist[start] = 0;

    Heap pq;
    heap_init(&pq, n + 5);
    heap_push(&pq, start, 0);

    while (!heap_empty(&pq)) {
        HeapNode cur = heap_pop(&pq);
        int u = cur.v;
        ll d = cur.d;
        if (d != dist[u]) continue;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heap_push(&pq, v, nd);
            }
        }
    }

    free(pq.a);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int S, A, B;
    scanf("%d %d %d", &S, &A, &B);

    Edge *g = (Edge *)malloc(sizeof(Edge) * M);
    Edge *rg = (Edge *)malloc(sizeof(Edge) * M);
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *rhead = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) head[i] = rhead[i] = -1;

    int idx1 = 0, idx2 = 0;
    for (int i = 0; i < M; i++) {
        int u, v;
        ll c;
        scanf("%d %d %lld", &u, &v, &c);
        add_edge(g, head, &idx1, u, v, c);
        add_edge(rg, rhead, &idx2, v, u, c);
    }

    ll *distS = (ll *)malloc(sizeof(ll) * (N + 1));
    ll *distA = (ll *)malloc(sizeof(ll) * (N + 1));
    ll *distB = (ll *)malloc(sizeof(ll) * (N + 1));

    dijkstra(N, S, head, g, distS);
    dijkstra(N, A, rhead, rg, distA); // distance i -> A in original graph
    dijkstra(N, B, rhead, rg, distB); // distance i -> B in original graph

    const ll INF = (1LL << 60);
    ll ans = INF;

    for (int i = 1; i <= N; i++) {
        if (distS[i] >= INF || distA[i] >= INF || distB[i] >= INF) continue;
        ll sum = distS[i] + distA[i] + distB[i];
        if (sum < ans) ans = sum;
    }

    if (ans >= INF) printf("-1\n");
    else printf("%lld\n", ans);

    free(g);
    free(rg);
    free(head);
    free(rhead);
    free(distS);
    free(distA);
    free(distB);

    return 0;
}

