using namespace std;

typedef long long ll;
const ll INF = 1e18;

struct Edge {
    int to, rev;
    ll cap, cost;
};

class MinCostFlow {
public:
    int n;
    vector<vector<Edge>> graph;
    vector<ll> dist, h;
    vector<int> prevv, preve;

    MinCostFlow(int n) : n(n), graph(n), dist(n), h(n, 0), prevv(n), preve(n) {}

    void add_edge(int from, int to, ll cap, ll cost) {
        graph[from].push_back({to, (int)graph[to].size(), cap, cost});
        graph[to].push_back({from, (int)graph[from].size() - 1, 0, -cost});
    }

    ll min_cost_flow(int s, int t, ll f) {
        ll res = 0;
        fill(h.begin(), h.end(), 0);
        while (f > 0) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (dist[v] < d) continue;
                for (int i = 0; i < (int)graph[v].size(); i++) {
                    Edge &e = graph[v][i];
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({dist[e.to], e.to});
                    }
                }
            }
            if (dist[t] == INF) return -1;
            for (int v = 0; v < n; v++) h[v] += dist[v];
            ll d = f;
            for (int v = t; v != s; v = prevv[v]) {
                d = min(d, graph[prevv[v]][preve[v]].cap);
            }
            f -= d;
            res += d * h[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = graph[prevv[v]][preve[v]];
                e.cap -= d;
                graph[v][e.rev].cap += d;
            }
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, S, T1, T2;
    cin >> N >> M >> S >> T1 >> T2;
    S--; T1--; T2--;

    MinCostFlow mcf(N);
    for (int i = 0; i < M; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        a--; b--;
        mcf.add_edge(a, b, 1, c);
        mcf.add_edge(b, a, 1, c);
    }

    // Find min cost to send 2 units from S to T1 and T2
    // We can try both orders: first to T1 then T2, or first to T2 then T1
    ll ans = INF;
    // Case 1: S -> T1, then T1 -> T2
    MinCostFlow mcf1(N);
    for (int i = 0; i < N; i++) {
        for (auto &e : mcf.graph[i]) {
            if (e.cap > 0) {
                mcf1.add_edge(i, e.to, e.cap, e.cost);
            }
        }
    }
    ll cost1 = mcf1.min_cost_flow(S, T1, 1);
    if (cost1 != -1) {
        ll cost2 = mcf1.min_cost_flow(T1, T2, 1);
        if (cost2 != -1) ans = min(ans, cost1 + cost2);
    }

    // Case 2: S -> T2, then T2 -> T1
    MinCostFlow mcf2(N);
    for (int i = 0; i < N; i++) {
        for (auto &e : mcf.graph[i]) {
            if (e.cap > 0) {
                mcf2.add_edge(i, e.to, e.cap, e.cost);
            }
        }
    }
    cost1 = mcf2.min_cost_flow(S, T2, 1);
    if (cost1 != -1) {
        ll cost2 = mcf2.min_cost_flow(T2, T1, 1);
        if (cost2 != -1) ans = min(ans, cost1 + cost2);
    }

    // Case 3: Send both from S directly, but since pipes are unidirectional and we need two separate paths,
    // we can use a super source and super sink approach.
    // Actually, we can add a dummy source with edges to S (cap=2, cost=0) and dummy sink with edges from T1 and T2 (cap=1, cost=0)
    MinCostFlow mcf3(N + 2);
    int src = N, snk = N + 1;
    mcf3.add_edge(src, S, 2, 0);
    mcf3.add_edge(T1, snk, 1, 0);
    mcf3.add_edge(T2, snk, 1, 0);
    for (int i = 0; i < N; i++) {
        for (auto &e : mcf.graph[i]) {
            if (e.cap > 0) {
                mcf3.add_edge(i, e.to, e.cap, e.cost);
            }
        }
    }
    ll cost3 = mcf3.min_cost_flow(src, snk, 2);
    if (cost3 != -1) ans = min(ans, cost3);

    cout << ans << "\n";
    return 0;
}

