#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    while (cin >> N >> M) {
        if (N == 0 && M == 0) break;

        int S, T1, T2;
        cin >> S >> T1 >> T2;
        --S; --T1; --T2;

        vector<vector<pair<int,int>>> g(N), rg(N);
        vector<tuple<int,int,int>> edges;

        for (int i = 0; i < M; ++i) {
            int u, v, c;
            cin >> u >> v >> c;
            --u; --v;
            g[u].push_back({v, c});
            rg[v].push_back({u, c});
            edges.push_back({u, v, c});
        }

        auto dijkstra = [&](int src, const vector<vector<pair<int,int>>> &graph) {
            vector<ll> dist(N, INF);
            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
            dist[src] = 0;
            pq.push({0, src});
            while (!pq.empty()) {
                auto [d, u] = pq.top();
                pq.pop();
                if (d != dist[u]) continue;
                for (auto [v, w] : graph[u]) {
                    if (dist[v] > d + w) {
                        dist[v] = d + w;
                        pq.push({dist[v], v});
                    }
                }
            }
            return dist;
        };

        // dist from source to every node
        vector<ll> ds = dijkstra(S, g);

        // dist from every node to T1 / T2
        vector<ll> dt1 = dijkstra(T1, rg);
        vector<ll> dt2 = dijkstra(T2, rg);

        ll ans = INF;

        // Case 1:
        // share prefix from S to some split node v, then branch to T1 and T2
        for (int v = 0; v < N; ++v) {
            if (ds[v] < INF && dt1[v] < INF && dt2[v] < INF) {
                ans = min(ans, ds[v] + dt1[v] + dt2[v]);
            }
        }

        // Case 2:
        // two branches merge at some node v and share suffix to one target.
        // For target T1:
        // S -> ... -> T2, and S -> ... -> v -> ... -> T1
        // Equivalent cost = shortest(S->v) + shortest(v->T1) + shortest(S->T2 avoiding double count through shared prefix)
        //
        // This can be represented by considering an edge u->v where paths to T1 and T2 diverge/merge.
        // More simply, symmetric "share suffix" is handled by reversing all edges:
        // In reversed graph, it becomes "share prefix" from T1/T2 to S.
        // Thus compute:
        // min_v dist(T1->v in reversed original?) + dist(T2->v) + dist(v->S)
        // which in original is dist(v->T1)+dist(v->T2)+dist(S->v)
        // already same as Case 1.
        //
        // However, because directions matter and the actual optimal directed arborescence
        // can be either out-branching from S or in-branching into a target after one branch
        // reaches the other target, we must also consider:
        // S->T1 plus some node on that path branching to T2, and S->T2 plus some node branching to T1.
        //
        // These are also covered by the same formula over all v.
        //
        // Therefore the minimum directed Steiner tree for 3 terminals in this setting
        // is exactly min_v ds[v] + dt1[v] + dt2[v].

        if (ans >= INF) cout << -1 << '\n';
        else cout << ans << '\n';
    }

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static class Edge implements Comparable<Edge> {
        int u, v, cost;
        Edge(int u, int v, int cost) {
            this.u = u;
            this.v = v;
            this.cost = cost;
        }
        public int compareTo(Edge o) {
            return Integer.compare(this.cost, o.cost);
        }
    }

    static int[] parent;
    static int[] rank;

    static int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    static boolean union(int x, int y) {
        int px = find(x);
        int py = find(y);
        if (px == py) return false;
        if (rank[px] < rank[py]) {
            parent[px] = py;
        } else if (rank[px] > rank[py]) {
            parent[py] = px;
        } else {
            parent[py] = px;
            rank[px]++;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int s = Integer.parseInt(st.nextToken());
        int t1 = Integer.parseInt(st.nextToken());
        int t2 = Integer.parseInt(st.nextToken());

        List<Edge> edges = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            int cost = Integer.parseInt(st.nextToken());
            edges.add(new Edge(u, v, cost));
        }

        // Build MST
        Collections.sort(edges);
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        List<Edge> mstEdges = new ArrayList<>();
        for (Edge e : edges) {
            if (union(e.u, e.v)) {
                mstEdges.add(e);
            }
        }

        // Build adjacency list for MST
        List<List<Edge>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (Edge e : mstEdges) {
            adj.get(e.u).add(new Edge(e.u, e.v, e.cost));
            adj.get(e.v).add(new Edge(e.v, e.u, e.cost));
        }

        // Find paths from s to t1 and s to t2 using DFS to get max edge on path
        int[] maxToT1 = new int[n];
        int[] maxToT2 = new int[n];
        Arrays.fill(maxToT1, -1);
        Arrays.fill(maxToT2, -1);
        dfs(s, -1, 0, adj, maxToT1);
        dfs(s, -1, 0, adj, maxToT2);

        // Get path max from s to t1 and s to t2
        int max1 = getMaxOnPath(s, t1, adj, maxToT1);
        int max2 = getMaxOnPath(s, t2, adj, maxToT2);

        // Now we need to find the minimum possible maximum edge cost for both paths
        // We can also consider that the two paths may share some edges
        // The answer is the minimum over all possible choices of two paths (one to t1, one to t2)
        // of the maximum edge used in either path.
        // Since we already have MST, the optimal is to take the MST and then possibly remove the
        // most expensive edge that is not needed, but actually we need to consider the Steiner tree
        // connecting s, t1, t2 with minimum possible maximum edge.
        // This is equivalent to finding the minimum value X such that the subgraph of edges with cost <= X
        // connects s to both t1 and t2.
        // We can binary search X and check connectivity.

        // First collect all unique edge costs
        Set<Integer> costs = new HashSet<>();
        for (Edge e : edges) {
            costs.add(e.cost);
        }
        List<Integer> sortedCosts = new ArrayList<>(costs);
        Collections.sort(sortedCosts);

        int lo = 0, hi = sortedCosts.size() - 1;
        int ans = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            int limit = sortedCosts.get(mid);
            if (canConnect(limit, edges, n, s, t1, t2)) {
                ans = limit;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }

        System.out.println(ans);
    }

    static void dfs(int u, int p, int maxSoFar, List<List<Edge>> adj, int[] maxArr) {
        maxArr[u] = maxSoFar;
        for (Edge e : adj.get(u)) {
            if (e.v == p) continue;
            dfs(e.v, u, Math.max(maxSoFar, e.cost), adj, maxArr);
        }
    }

    static int getMaxOnPath(int s, int t, List<List<Edge>> adj, int[] maxArr) {
        // Since we stored max from s to each node during dfs, just return maxArr[t]
        return maxArr[t];
    }

    static boolean canConnect(int limit, List<Edge> edges, int n, int s, int t1, int t2) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        for (Edge e : edges) {
            if (e.cost <= limit) {
                union(e.u, e.v);
            }
        }
        return find(s) == find(t1) && find(s) == find(t2);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static final long INF = Long.MAX_VALUE / 2;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int S = Integer.parseInt(st.nextToken()) - 1;
        int T1 = Integer.parseInt(st.nextToken()) - 1;
        int T2 = Integer.parseInt(st.nextToken()) - 1;

        List<int[]>[] fwd = new List[n];
        List<int[]>[] rev = new List[n];
        for (int i = 0; i < n; i++) { fwd[i] = new ArrayList<>(); rev[i] = new ArrayList<>(); }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            int w = Integer.parseInt(st.nextToken());
            fwd[u].add(new int[]{v, w});
            rev[v].add(new int[]{u, w});
        }

        long[] dS = dijkstra(S, fwd, n);
        long[] dT1 = dijkstra(T1, rev, n);
        long[] dT2 = dijkstra(T2, rev, n);

        long ans = INF;
        for (int v = 0; v < n; v++) {
            if (dS[v] < INF && dT1[v] < INF && dT2[v] < INF)
                ans = Math.min(ans, dS[v] + dT1[v] + dT2[v]);
        }
        System.out.println(ans == INF ? -1 : ans);
    }

    static long[] dijkstra(int src, List<int[]>[] g, int n) {
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        pq.offer(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[1];
            if (cur[0] > dist[u]) continue;
            for (int[] e : g[u]) {
                if (dist[u] + e[1] < dist[e[0]]) {
                    dist[e[0]] = dist[u] + e[1];
                    pq.offer(new long[]{dist[e[0]], e[0]});
                }
            }
        }
        return dist;
    }
}

import java.io.*;
import java.util.*;

/*
We need the minimum cost to lay directed water pipes from one source base to two target bases
using existing directed roads with costs.

This is the classic "minimum arborescence to connect one root to two terminals" on a directed graph.
Since there are only two destination bases, the optimal structure has one branching point x:
root -> x, x -> t1, x -> t2.
Paths may share a prefix up to x.

Therefore answer = min over all vertices x:
dist(source, x) + dist(x, target1) + dist(x, target2)

We can compute:
- dist from source to all vertices on original graph
- dist to target1 from all vertices by running Dijkstra from target1 on reversed graph
- dist to target2 from all vertices by running Dijkstra from target2 on reversed graph

Then take the minimum sum.

Assumed input format:
N M
S T1 T2
u v w   (M lines, directed edge u -> v with cost w)

Vertices are 1-indexed.

If impossible, print -1.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    static long[] dijkstra(List<Edge>[] g, int start) {
        int n = g.length - 1;
        long[] dist = new long[n + 1];
        Arrays.fill(dist, INF);
        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[start] = 0;
        pq.add(new Node(start, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;
            for (Edge e : g[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new Node(e.to, nd));
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();
        int s = fs.nextInt();
        int t1 = fs.nextInt();
        int t2 = fs.nextInt();

        List<Edge>[] g = new ArrayList[n + 1];
        List<Edge>[] rg = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            long w = fs.nextLong();
            g[u].add(new Edge(v, w));
            rg[v].add(new Edge(u, w));
        }

        long[] ds = dijkstra(g, s);
        long[] dt1 = dijkstra(rg, t1);
        long[] dt2 = dijkstra(rg, t2);

        long ans = INF;
        for (int x = 1; x <= n; x++) {
            if (ds[x] == INF || dt1[x] == INF || dt2[x] == INF) continue;
            ans = Math.min(ans, ds[x] + dt1[x] + dt2[x]);
        }

        System.out.println(ans == INF ? -1 : ans);
    }
}
